  --bg-card: #1a1d27;
  --bg-field: #13151f;
  --border: #2e3147;
  --border-focus: #5b63f5;
  --accent: #5b63f5;
  --accent-hover: #7079ff;
  --accent-light: rgba(91, 99, 245, 0.12);
  --text-primary: #e8eaf6;
  --text-secondary: #8b90b8;
  --text-help: #636888;
  --success: #4caf7d;
  --error: #e05c6e;
  --check-size: 20px;
  --radius: 10px;
  --transition: 0.18s ease;
}

body {
  background: var(--bg-base);
  color: var(--text-primary);
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 16px 80px;
}

.quiz-wrapper {
  width: 100%;
  max-width: 680px;
}

.quiz-header {
  margin-bottom: 40px;
  text-align: center;
}

.quiz-header .badge {
  display: inline-block;
  background: var(--accent-light);
  color: var(--accent-hover);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 100px;
  border: 1px solid rgba(91, 99, 245, 0.3);
  margin-bottom: 16px;
}

.quiz-header h1 {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: 8px;
}

.quiz-header p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ── Form Field ── */
.form-field {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  margin-bottom: 16px;
  transition: border-color var(--transition);
}

.form-field:focus-within {
  border-color: rgba(91, 99, 245, 0.4);
}

.field-header {
  margin-bottom: 16px;
}

.question-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.question-number {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
  background: var(--accent-light);
  padding: 3px 9px;
  border-radius: 100px;
}

.multi-label {
  font-size: 11px;
  color: var(--text-help);
  font-style: italic;
}

.field-question {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.5;
}

.field-help {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  background: rgba(91, 99, 245, 0.07);
  border: 1px solid rgba(91, 99, 245, 0.2);
  border-radius: 7px;
  padding: 10px 14px;
  margin-top: 12px;
  margin-bottom: 4px;
}

.field-help svg {
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--accent);
}

.field-help span {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.55;
}

/* ── Checkbox Options ── */
.options-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.option-label {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--bg-field);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 13px 16px;
  cursor: pointer;
  user-select: none;
  transition: background var(--transition), border-color var(--transition);
}

.option-label:hover {
  background: rgba(255,255,255,0.03);
  border-color: rgba(91, 99, 245, 0.35);
}

.option-label.selected {
  background: var(--accent-light);
  border-color: rgba(91, 99, 245, 0.55);
}

/* visually hidden native checkbox */
.option-label input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.custom-check {
  flex-shrink: 0;
  width: var(--check-size);
  height: var(--check-size);
  border: 2px solid var(--border);
  border-radius: 5px;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), border-color var(--transition);
  pointer-events: none;
}

.option-label.selected .custom-check {
  background: var(--accent);
  border-color: var(--accent);
}

.custom-check svg {
  opacity: 0;
  transform: scale(0.6);
  transition: opacity var(--transition), transform var(--transition);
}

.option-label.selected .custom-check svg {
  opacity: 1;
  transform: scale(1);
}

.option-text {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-primary);
  line-height: 1.4;
}

/* ── Submit ── */
.submit-area {
  margin-top: 28px;
  display: flex;
  align-items: center;
  gap: 16px;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--accent);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  padding: 13px 32px;
  border: none;
  border-radius: 9px;
  cursor: pointer;
  letter-spacing: 0.01em;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 4px 18px rgba(91, 99, 245, 0.35);
}

.btn-submit:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 6px 24px rgba(91, 99, 245, 0.45);
}

.btn-submit:active {
  transform: translateY(0);
}

.selection-hint {
  font-size: 13px;
  color: var(--text-help);
}

/* ── Results Banner ── */
.results-banner {
  display: none;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  margin-top: 20px;
  text-align: center;
}

.results-banner.visible {
  display: block;
  animation: fadeUp 0.3s ease;
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

.results-banner .score {
  font-size: 40px;
  font-weight: 800;
  letter-spacing: -0.03em;
  background: linear-gradient(135deg, var(--accent), var(--accent-hover));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 4px;
}

.results-banner .result-msg {
  font-size: 15px;
  color: var(--text-secondary);
  margin-bottom: 18px;
}

.answer-review {
  display: flex;
  flex-direction: column;
  gap: 8px;
  text-align: left;
}

.review-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  color: var(--text-secondary);
  padding: 10px 14px;
  border-radius: 7px;
  background: var(--bg-field);
  border: 1px solid var(--border);
}

.review-item .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.review-item.correct { border-color: rgba(76, 175, 125, 0.3); }
.review-item.correct .dot { background: var(--success); }
.review-item.incorrect { border-color: rgba(224, 92, 110, 0.3); }
.review-item.incorrect .dot { background: var(--error); }

.review-item .review-q {
  flex: 1;
  font-weight: 500;
  color: var(--text-primary);
  font-size: 13px;
}

.review-item .review-ans {
  font-size: 12px;
  color: var(--text-help);
}

.divider {
  border: none;
  border-top: 1px solid var(--border);
  margin: 18px 0;
}
