    el("h1", {}, "Computer Languages Quiz"),
    el("p", {}, "Test your knowledge of programming language concepts. Each question may have multiple correct answers.")
  );

  const fields = QUESTIONS.map(FormFieldComponent);

  const hint = el("span", { className: "selection-hint", id: "selection-hint" },
