  const resultsBanner = el("div", { className: "results-banner", id: "results-banner" });

  const form = el("form", { id: "quiz-form" }, ...fields, submitArea, resultsBanner);

  form.addEventListener("submit", handleSubmit);

  return el("div", { className: "quiz-wrapper" }, header, form);
}

// ── Logic ───────────────────────────────────────────────────────────────────
function totalSelections() {
  return Object.values(selections).reduce((n, s) => n + s.size, 0);
}

