      .map(o => o.label)
      .join(", ") || "None selected";
    const correctLabels = q.options
      .filter(o => q.correct.has(o.id))
      .map(o => o.label)
      .join(", ");
    return { question: q.text, isCorrect, selectedLabels, correctLabels };
  });

  const banner = document.getElementById("results-banner");
  if (!banner) return;

  // Clear previous results
  banner.innerHTML = "";

  const total = QUESTIONS.length;
  const pct = Math.round((correct / total) * 100);
  const msgs = ["Keep studying — you'll get there! 📚", "Good effort! Review the answers below. 🙂", "Great job! You know your languages! 🎉"];
  const msgIdx = correct === 0 ? 0 : correct < total ? 1 : 2;

  banner.appendChild(el("div", { className: "score" }, `${correct} / ${total}`));
