  banner.appendChild(el("hr", { className: "divider" }));

  const reviewList = el("div", { className: "answer-review" });
  reviewItems.forEach(item => {
    const row = el("div", { className: `review-item ${item.isCorrect ? "correct" : "incorrect"}` },
      el("span", { className: "dot" }),
      el("span", { className: "review-q" }, item.question),
      el("span", { className: "review-ans" },
        item.isCorrect
          ? "✓ Correct"
          : `Your answer: ${item.selectedLabels}`
      )
    );
    reviewList.appendChild(row);

    if (!item.isCorrect) {
      const correctRow = el("div", { className: "review-item" },
        el("span", { className: "dot", style: "background: var(--accent);" }),
        el("span", { className: "review-q", style: "color: var(--text-secondary); font-weight: 400;" }, "Correct answer:"),
        el("span", { className: "review-ans", style: "color: var(--accent-hover);" }, item.correctLabels)
      );
      reviewList.appendChild(correctRow);
    }
  });

  banner.appendChild(reviewList);
  banner.classList.add("visible");
  banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

// ── Mount ───────────────────────────────────────────────────────────────────
document.addEventListener("DOMContentLoaded", () => {
  document.body.appendChild(QuizComponent());
});
